net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builderSize = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
builderSize.size(50, 50);
net.coobird.thumbnailator.ThumbnailParameter paramSize = builderSize.build();

java.awt.Dimension size = paramSize.getSize();
assert size != null : "Size should not be null when explicitly set";
assert size.width == 50 && size.height == 50 : "Size should be 50x50";

net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builderScale = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
builderScale.scale(2.0);
net.coobird.thumbnailator.ThumbnailParameter paramScale = builderScale.build();

java.awt.Dimension sizeNull = paramScale.getSize();
assert sizeNull == null : "Size should be null when scaling factor is used";

System.out.println("__CHECK__ getSize " + size.width + "x" + size.height + " and null");
